// CSD_RATIONALE_BEGIN
// Root-cause of 0% accuracy in attempt 70 (and regression from best 40.8%):
//   With `RenderedEndsWith` required, every `<<` (including space-prefixed `" <<"`)
//   triggers constrained mode. The model writes 15+ tiny spans per example
//   (`<<n1>>`, `<<price>>`, `<<w1>>`, …). The evaluator extracts the LAST visible
//   span as the answer, which is always a tiny fragment like `<<price>>` → 0%.
//
// Fix strategy:
//   Phase 0: If called with an already-open span, close it quickly with up to
//            RESERVE steps via CloseSpanWithinBudget, then proceed.
//   Phase 1: Generate FULLY UNCONSTRAINED for most of the budget. Never enter
//            constrained mode even when RenderedEndsWith(generated, "<<") fires.
//            The model writes its reasoning + intermediate << >> spans naturally
//            as free text. These are still parser-valid per prior observation
//            (syntax was 100% in all recent attempts).
//   Phase 2: After EOS or when budget ≤ RESERVE, force-open ONE single
//            constrained span via OpenConstrainedSpan. Use CloseSpanWithinBudget
//            with the remaining budget to generate the COMPLETE combined formula.
//            The evaluator's last visible span is always this Phase-2 span.
//
// Guidance: direct the model to write the final combined expression at the end.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 0 (pre-existing close, CloseSpanWithinBudget):
//     Postcondition directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//   Phase 1 (UnconstrainedStep, no span entry):
//     insideConstrainedOut is false (or unchanged if still true after Phase 0).
//     We never modify insideConstrainedOut or currentConstrainedOut here, so
//     the invariant is preserved by the previous iteration. ✓
//   Phase 2 open (OpenConstrainedSpan):
//     Sets insideConstrainedOut := true, currentConstrainedOut := [].
//     parser.IsValidPrefix([]) holds by method precondition. ✓
//   Phase 2 close (CloseSpanWithinBudget):
//     Postcondition directly guarantees parser_validity. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: |generatedPrefix| <= |generatedPrefix| + 0. ✓
//   Phase 0: CloseSpanWithinBudget postcondition: |cg| <= |generated| + closeB.
//     After steps := steps + closeB: |cg| <= |generatedPrefix| + steps. ✓
//   Phase 1 UnconstrainedStep, non-EOS: steps += 1, generated += 1 token.
//     |generated| + 1 <= |generatedPrefix| + steps + 1 = |generatedPrefix| + steps'. ✓
//   Phase 1 UnconstrainedStep, EOS: steps += 1, generated unchanged.
//     |generated| <= |generatedPrefix| + steps < |generatedPrefix| + steps'. ✓
//   Phase 2 OpenConstrainedSpan: steps += 1, generated grows by 1 ("<<"). ✓
//   Phase 2 CloseSpanWithinBudget(closeB): |cg| <= |generated| + closeB.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step in plain text. " +
  "At the very end of your solution, write the COMPLETE combined final answer as ONE " +
  "arithmetic expression inside a single << >> delimiter. " +
  "Put ALL variables and operations together in that one expression. " +
  "Example: <<(w1 + w2 + w3) * price>> or <<n - n_1 - 3*n_2>>. " +
  "Do NOT write multiple << >> for sub-expressions; reserve << >> for the final answer only.");

var steps: nat := 0;
var RESERVE: nat := 80;

// Phase 0: Close any pre-existing open span before unconstrained generation.
if insideConstrainedOut && steps < maxSteps {
  var avail0: nat := maxSteps - steps;
  var closeB0: nat := if avail0 <= RESERVE then avail0 else RESERVE;
  var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB0
  );
  generated := cg0;
  insideConstrainedOut := ci0;
  currentConstrainedOut := cc0;
  steps := steps + closeB0;
}

// Phase 1: Generate unconstrained reasoning. Do NOT enter constrained mode.
// Stop when budget is within RESERVE of maxSteps or EOS is hit.
while steps + RESERVE < maxSteps && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  // Intentionally NOT calling EnterObservedConstrainedSpan even if
  // RenderedEndsWith(generated, "<<") — intermediate spans stay unconstrained free text.
}

// Phase 2: Force ONE final constrained span for the complete answer.
if steps < maxSteps && !insideConstrainedOut {
  // Open the final answer span.
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;

  // Close the span with all remaining budget.
  if steps < maxSteps {
    var closeB2: nat := maxSteps - steps;
    var cg2, ci2, cc2 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB2
    );
    generated := cg2;
    insideConstrainedOut := ci2;
    currentConstrainedOut := cc2;
    steps := maxSteps;
  }
}

cost := steps;

